package com.jadhavr.erp.reports.controller;
import com.jadhavr.erp.academic.repository.*; import com.jadhavr.erp.admission.entity.AdmissionForm; import com.jadhavr.erp.admission.enums.AdmissionStatus; import com.jadhavr.erp.admission.repository.AdmissionFormRepository; import com.jadhavr.erp.audit.enums.*; import com.jadhavr.erp.audit.service.AuditLogService; import com.jadhavr.erp.auth.security.SecurityUtils; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.fee.entity.StudentFeeAccount; import com.jadhavr.erp.fee.repository.StudentFeeAccountRepository; import com.jadhavr.erp.student.entity.StudentProfile; import com.jadhavr.erp.student.enums.StudentStatus; import com.jadhavr.erp.student.repository.StudentProfileRepository; import org.springframework.data.domain.PageRequest; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.util.*;
@Transactional(readOnly=true)
@RestController @RequestMapping("/api/reports") public class ReportController {private final AdmissionFormRepository admissions;private final StudentFeeAccountRepository fees;private final StudentProfileRepository students;private final AttendanceRecordRepository attendance;private final StudentSectionEnrollmentRepository enrollments;private final AuditLogService audit;public ReportController(AdmissionFormRepository a,StudentFeeAccountRepository f,StudentProfileRepository s,AttendanceRecordRepository at,StudentSectionEnrollmentRepository e,AuditLogService au){admissions=a;fees=f;students=s;attendance=at;enrollments=e;audit=au;}
 @GetMapping("/admissions") public ApiResponse<?> admissions(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){Long c=scope(collegeId);Specification<AdmissionForm>s=Specification.where(null);if(c!=null)s=s.and((r,q,b)->b.equal(r.get("college").get("id"),c));if(departmentId!=null)s=s.and((r,q,b)->b.equal(r.get("department").get("id"),departmentId));if(status!=null&&!status.isBlank()){AdmissionStatus value=AdmissionStatus.valueOf(status);s=s.and((r,q,b)->b.equal(r.get("status"),value));}var rows=admissions.findAll(s,PageRequest.of(validPage(page),validSize(size))).getContent().stream().map(x->Map.of("admissionReferenceNumber",x.getAdmissionReferenceNumber(),"admissionNumber",x.getStudent().getAdmissionNumber(),"studentName",x.getFullName(),"email",x.getEmail(),"phone",x.getPhone(),"collegeName",x.getCollege().getName(),"departmentName",x.getDepartment().getName(),"academicYear",x.getAcademicYear(),"status",x.getStatus(),"submittedAt",x.getSubmittedAt())).toList();view("Admission");return ApiResponse.success("Admission report",rows);}
 @GetMapping("/fees") public ApiResponse<?> fees(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){Long c=scope(collegeId);Specification<StudentFeeAccount>s=Specification.where(null);if(c!=null)s=s.and((r,q,b)->b.equal(r.get("college").get("id"),c));if(departmentId!=null)s=s.and((r,q,b)->b.equal(r.get("department").get("id"),departmentId));var rows=fees.findAll(s,PageRequest.of(validPage(page),validSize(size))).getContent().stream().map(x->Map.of("studentName",x.getStudent().getFullName(),"admissionNumber",x.getStudent().getAdmissionNumber(),"collegeName",x.getCollege().getName(),"departmentName",x.getDepartment().getName(),"totalFee",x.getTotalFee(),"paidAmount",x.getPaidAmount(),"remainingAmount",x.getRemainingAmount(),"feeStatus",x.getStatus())).toList();view("Fee");return ApiResponse.success("Fee report",rows);}
 @GetMapping("/students") public ApiResponse<?> students(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){Long c=scope(collegeId);Specification<StudentProfile>s=Specification.where(null);if(c!=null)s=s.and((r,q,b)->b.equal(r.get("college").get("id"),c));if(departmentId!=null)s=s.and((r,q,b)->b.equal(r.get("department").get("id"),departmentId));if(status!=null&&!status.isBlank()){StudentStatus value=StudentStatus.valueOf(status);s=s.and((r,q,b)->b.equal(r.get("status"),value));}var rows=students.findAll(s,PageRequest.of(validPage(page),validSize(size))).getContent().stream().map(x->Map.of("studentName",x.getFullName(),"rollNumber",Objects.toString(x.getRollNumber(),""),"email",x.getEmail(),"phone",x.getPhone(),"collegeName",x.getCollege().getName(),"departmentName",x.getDepartment().getName(),"studentStatus",x.getStatus())).toList();view("Student");return ApiResponse.success("Student report",rows);}
 @GetMapping("/attendance") public ApiResponse<?> attendance(@RequestParam(required=false)Long collegeId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){Long c=scope(collegeId);var rows=attendance.attendanceReport(c,PageRequest.of(validPage(page),validSize(size)));view("Attendance");return ApiResponse.success("Attendance report",rows);}
 @GetMapping(value="/{type:admissions|fees|attendance|students}/export",produces="text/csv") public ResponseEntity<byte[]> export(@PathVariable String type,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)String status){Long c=scope(collegeId);StringBuilder csv=new StringBuilder();switch(type){case "admissions"->{AdmissionStatus admissionStatus=status==null||status.isBlank()?null:AdmissionStatus.valueOf(status);csv.append("Reference,Admission Number,Student,College,Department,Status\n");admissions.findAll().stream().filter(x->c==null||x.getCollege().getId().equals(c)).filter(x->admissionStatus==null||x.getStatus()==admissionStatus).forEach(x->csv.append(q(x.getAdmissionReferenceNumber())).append(',').append(q(x.getStudent().getAdmissionNumber())).append(',').append(q(x.getFullName())).append(',').append(q(x.getCollege().getName())).append(',').append(q(x.getDepartment().getName())).append(',').append(x.getStatus()).append('\n'));}case "fees"->{csv.append("Student,Admission Number,Total,Paid,Remaining,Status\n");fees.findAll().stream().filter(x->c==null||x.getCollege().getId().equals(c)).forEach(x->csv.append(q(x.getStudent().getFullName())).append(',').append(q(x.getStudent().getAdmissionNumber())).append(',').append(x.getTotalFee()).append(',').append(x.getPaidAmount()).append(',').append(x.getRemainingAmount()).append(',').append(x.getStatus()).append('\n'));}default->{csv.append("Student,Roll Number,Status\n");students.findAll().stream().filter(x->c==null||x.getCollege().getId().equals(c)).forEach(x->csv.append(q(x.getFullName())).append(',').append(q(Objects.toString(x.getRollNumber(),""))).append(',').append(x.getStatus()).append('\n'));}}audit.log(AuditModule.REPORT,AuditAction.EXPORT,"Report",null,"Exported "+type+" report");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+type+"-report.csv").contentType(new MediaType("text","csv",StandardCharsets.UTF_8)).body(csv.toString().getBytes(StandardCharsets.UTF_8));}
 private Long scope(Long requested){if(SecurityUtils.isSuperAdmin())return requested;Long own=SecurityUtils.requireCurrentUser().getCollegeId();if(requested!=null&&!requested.equals(own))throw new org.springframework.security.access.AccessDeniedException("Report is outside your college");return own;}private int validPage(int page){if(page<0)throw new IllegalArgumentException("page must be zero or greater");return page;}private int validSize(int size){if(size<1||size>500)throw new IllegalArgumentException("size must be between 1 and 500");return size;}private void view(String name){audit.log(AuditModule.REPORT,AuditAction.VIEW_REPORT,"Report",null,"Viewed "+name+" report");}private String q(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}}
